           ROW_NUMBER() OVER (PARTITION BY COALESCE(v.[_environment], ''), v.[id]
               ORDER BY ISNULL(v.[lastModifiedDateTime], '1900-01-01') DESC, v.[_loadedAt] DESC) AS [_v]
      FROM [bcRaw].[purchaseBlanketOrders] v
)

SELECT c.[id], c.[bcCompanyId], c.[bcCompanyName], c.[number], c.[integrationId], c.[vendorNumber], c.[vendorName], c.[vendorIntegrationId], c.[orderDate], c.[documentDate], c.[currencyCode], c.[paymentTermsCode], c.[reasonCode], c.[purchaserCode], c.[locationCode], c.[pricesIncludeTax], c.[buyFromContact], c.[payToContact], c.[payToAddressLine1], c.[payToAddressLine2], c.[payToCity], c.[payToCounty], c.[payToPostCode], c.[payToCountryRegionCode], c.[shipToCode], c.[shipToName], c.[shipToAddressLine1], c.[shipToAddressLine2], c.[shipToCity], c.[shipToCounty], c.[shipToPostCode], c.[shipToCountryRegionCode], c.[shipToContact], c.[shipmentMethodCode], c.[vatRegistrationNumber], c.[taxLiable], c.[taxAreaCode], c.[dimensionSetId], c.[status], c.[lastModifiedDateTime],
       c.[_environment], c.[_loadedAt], c.[_firstLoadedAt], c.[_runNumber],
       CAST(COALESCE(CASE WHEN COALESCE(xi.[sequence], -1) >= COALESCE(xn.[sequence], -1)
                 THEN xi.[rowState] ELSE xn.[rowState] END, 'Active') AS varchar(10)) AS [_rowState],
       CAST(CASE WHEN COALESCE(xi.[sequence], -1) >= COALESCE(xn.[sequence], -1)
                 THEN xi.[exitedAt] ELSE xn.[exitedAt] END AS datetime2(6)) AS [_exitedAt],
       CAST(CASE WHEN COALESCE(xi.[sequence], -1) >= COALESCE(xn.[sequence], -1)
                 THEN xi.[exitRef] ELSE xn.[exitRef] END AS varchar(50)) AS [_exitRef]
  FROM latest c
  LEFT JOIN [bcModel].[vw_documentExit] xi ON xi.[entitySet] = 'purchaseBlanketOrders'
       AND xi.[bcCompanyId] = c.[bcCompanyId]
       AND COALESCE(xi.[_environment], '') = COALESCE(c.[_environment], '')
       AND xi.[matchKind] = 'id' AND xi.[matchId] = c.[id]
  LEFT JOIN [bcModel].[vw_documentExit] xn ON xn.[entitySet] = 'purchaseBlanketOrders'
       AND xn.[bcCompanyId] = c.[bcCompanyId]
       AND COALESCE(xn.[_environment], '') = COALESCE(c.[_environment], '')
       AND xn.[matchKind] = 'number' AND xn.[matchNumber] = c.[number]
       AND NOT (xn.[rowState] = 'Posted'
                AND ISNULL(c.[lastModifiedDateTime], '1900-01-01') > xn.[exitedAt])
 WHERE c.[_v] = 1;
