DROP VIEW IF EXISTS [bc].[warehouseReceipts];
GO
CREATE VIEW [bc].[warehouseReceipts] AS
WITH latest AS (
    SELECT v.*, MIN(v.[_loadedAt]) OVER (PARTITION BY COALESCE(v.[_environment], ''), v.[id]) AS [_firstLoadedAt],
           ROW_NUMBER() OVER (PARTITION BY COALESCE(v.[_environment], ''), v.[id]
               ORDER BY ISNULL(v.[lastModifiedDateTime], '1900-01-01') DESC, v.[_loadedAt] DESC) AS [_v]
      FROM [bcRaw].[warehouseReceipts] v
)

SELECT c.[id], c.[bcCompanyId], c.[bcCompanyName], c.[number], c.[integrationId], c.[locationCode], c.[zoneCode], c.[binCode], c.[documentStatus], c.[assignedUserId], c.[postingDate], c.[vendorShipmentNumber], c.[shippingAgentCode], c.[shippingAgentServiceCode], c.[receiptDate], c.[totalWeight], c.[totalVolume], c.[createdDateTime], c.[lastModifiedDateTime],
       c.[_environment], c.[_loadedAt], c.[_firstLoadedAt], c.[_runNumber],
       CAST(COALESCE(CASE WHEN COALESCE(xi.[sequence], -1) >= COALESCE(xn.[sequence], -1)
                 THEN xi.[rowState] ELSE xn.[rowState] END, 'Active') AS varchar(10)) AS [_rowState],
       CAST(CASE WHEN COALESCE(xi.[sequence], -1) >= COALESCE(xn.[sequence], -1)
                 THEN xi.[exitedAt] ELSE xn.[exitedAt] END AS datetime2(6)) AS [_exitedAt],
       CAST(CASE WHEN COALESCE(xi.[sequence], -1) >= COALESCE(xn.[sequence], -1)
                 THEN xi.[exitRef] ELSE xn.[exitRef] END AS varchar(50)) AS [_exitRef]
  FROM latest c
  LEFT JOIN [bcModel].[vw_documentExit] xi ON xi.[entitySet] = 'warehouseReceipts'
       AND xi.[bcCompanyId] = c.[bcCompanyId]
       AND COALESCE(xi.[_environment], '') = COALESCE(c.[_environment], '')
       AND xi.[matchKind] = 'id' AND xi.[matchId] = c.[id]
  LEFT JOIN [bcModel].[vw_documentExit] xn ON xn.[entitySet] = 'warehouseReceipts'
       AND xn.[bcCompanyId] = c.[bcCompanyId]
       AND COALESCE(xn.[_environment], '') = COALESCE(c.[_environment], '')
       AND xn.[matchKind] = 'number' AND xn.[matchNumber] = c.[number]
       AND NOT (xn.[rowState] = 'Posted'
                AND ISNULL(c.[lastModifiedDateTime], '1900-01-01') > xn.[exitedAt])
 WHERE c.[_v] = 1;
GO

